// Inlined icon set — matches the ~18 Lucide icons this app uses. Kept as
// plain inline SVGs rather than an external icon library dependency, since
// this is now a real standalone page and these icons never change.
function makeIcon(paths) {
  return function Icon({ size = 24, className, style, ...rest }) {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor"
        strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className} style={style} {...rest}>
        {paths}
      </svg>
    );
  };
}

