// Mirrors window.storage's async, {value}-wrapped API but backs onto real
// localStorage — for settings that are genuinely per-device (auth token,
// dark mode, nav layout, active timer, today's route order), not business
// data shared across the crew. window.storage only exists inside Claude's
// own chat/artifact preview; it does not exist on a real deployed page.
const localStore = {
  async get(key) {
    try {
      const v = localStorage.getItem(key);
      return v === null ? null : { value: v };
    } catch (e) {
      return null;
    }
  },
  async set(key, value) {
    try {
      localStorage.setItem(key, value);
      return true;
    } catch (e) {
      return false;
    }
  },
  async delete(key) {
    try {
      localStorage.removeItem(key);
      return true;
    } catch (e) {
      return false;
    }
  },
};
